import numpy as np
from PIL import Image
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
r,g,b=im.transpose(2,0,1)
blue=(b>r+12)&(g>r+5)&(b>85)
brown=(r>g+10)&(g>b+8)&(b<90)&(r>50)
orange=(r>g+24)&(g>b+8)&(r>120)&(b<110)
light=(np.maximum.reduce([r,g,b])-np.minimum.reduce([r,g,b])<24)&((r+g+b)/3>115)
dark=(np.maximum.reduce([r,g,b])-np.minimum.reduce([r,g,b])<30)&((r+g+b)/3<=115)
def runs(a,lo=70,hi=221):
 out=[]; s=lo; prev=a[lo]
 for x in range(lo+1,hi):
  if a[x]"'!=prev:
   if x-s>=2: out.append(f'"'{prev}{s}-{x-1}')
   s=x; prev=a[x]
 if hi-s>=2: out.append(f'{prev}{s}-{hi-1}')
 return ' '.join(out)
chars=np.full((144,256),'.',dtype='<U1'); chars[blue]='B'; chars[brown]='w'; chars[orange]='O'; chars[light]='L'; chars[dark]='d'
for y in range(20,126,2):
 print(f'{y:3d}', ''.join(chars[y,80:221:2]))
print('rows detailed runs x=80..220')
for y in [24,30,36,42,48,54,60,66,72,78,84,90,96,102,108,114,120]:
 print(f'y={y:3d} B[{runs(blue[y])}] W[{runs(brown[y])}] O[{runs(orange[y])}] L[{runs(light[y])}]')
PY"

